import glob, re, zlib, base64

def process_pdf(path):
    with open(path, 'rb') as f:
        content = f.read()
    streams = re.findall(b'stream\r?\n(.*?)\r?\nendstream', content, re.DOTALL)
    text_chunks = []
    for s in streams:
        data = s.strip()
        # Handle ASCII85 decode if needed
        if data.endswith(b'~>'):
            try:
                data = base64.a85decode(data, adobe=True)
            except Exception as e:
                pass
        try:
            decomp = zlib.decompress(data)
            text_chunks.append(decomp.decode('latin1', errors='ignore'))
        except Exception:
            text_chunks.append(data.decode('latin1', errors='ignore'))
    full_text = ' '.join(text_chunks)
    if any(k in full_text for k in ['7B', 'Mesa Vista', 'Hill Country', 'exchanger', 'thermocouple', '201']):
        print(f'=== MATCH IN {path} ===')
        print(full_text)

for pdf in glob.glob('company_files/**/*.pdf', recursive=True):
    process_pdf(pdf)
